'use strict';

// ── Navbar scroll effect ──────────────────────────────────────────────────────
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  navbar.classList.toggle('scrolled', window.scrollY > 20);
}, { passive: true });

// ── Mobile hamburger ──────────────────────────────────────────────────────────
const hamburger   = document.getElementById('hamburger');
const mobileMenu  = document.getElementById('mobileMenu');

hamburger.addEventListener('click', () => {
  mobileMenu.classList.toggle('open');
});

// Close mobile menu when a link is clicked
mobileMenu.querySelectorAll('a').forEach(a => {
  a.addEventListener('click', () => mobileMenu.classList.remove('open'));
});

// ── AOS (scroll-triggered fade-in) ───────────────────────────────────────────
function initAos() {
  const els = document.querySelectorAll('[data-aos]');
  const delays = { '0': 0, '60': 60, '100': 100, '120': 120, '180': 180, '200': 200, '240': 240, '300': 300 };

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const delay = parseInt(entry.target.getAttribute('data-aos-delay') || '0', 10);
        setTimeout(() => {
          entry.target.classList.add('aos-animate');
        }, delay);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });

  els.forEach(el => observer.observe(el));
}

initAos();

// ── Typewriter effect on terminal ─────────────────────────────────────────────
function typewrite(el, text, speed, onDone) {
  let i = 0;
  el.textContent = '';
  const timer = setInterval(() => {
    el.textContent += text[i];
    i++;
    if (i >= text.length) {
      clearInterval(timer);
      if (onDone) onDone();
    }
  }, speed);
}

let terminalPlayed = false;
const terminalEl = document.querySelector('.terminal-mockup');
const typedCmd   = document.getElementById('typedCmd');
const termResult = document.getElementById('terminalResult');

const termObserver = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting && !terminalPlayed) {
    terminalPlayed = true;
    setTimeout(() => {
      typewrite(typedCmd, 'apk-builder', 80, () => {
        setTimeout(() => {
          termResult.style.display = '';
        }, 400);
      });
    }, 600);
    termObserver.unobserve(terminalEl);
  }
}, { threshold: 0.5 });

if (terminalEl) termObserver.observe(terminalEl);

// ── Animated stat counters ────────────────────────────────────────────────────
function animateCounter(el, target, suffix) {
  let start = 0;
  const duration = 1400;
  const startTime = performance.now();
  const isZero = target === 0;

  if (isZero) { el.textContent = '0' + suffix; return; }

  function step(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const ease = 1 - Math.pow(1 - progress, 3);
    el.textContent = Math.round(ease * target) + suffix;
    if (progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

const statObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const el = entry.target.querySelector('.stat-num');
      const target = parseInt(el.getAttribute('data-target'), 10);
      const suffix = el.textContent.includes('%') ? '%' : '';
      animateCounter(el, target, '');
      statObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.6 });

document.querySelectorAll('.stat-item').forEach(el => statObserver.observe(el));

// ── FAQ accordion ─────────────────────────────────────────────────────────────
document.querySelectorAll('.faq-q').forEach(btn => {
  btn.addEventListener('click', () => {
    const item = btn.closest('.faq-item');
    const isOpen = item.classList.contains('open');
    // Close all
    document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
    // Open clicked (unless it was already open)
    if (!isOpen) item.classList.add('open');
  });
});

// ── Install tabs ──────────────────────────────────────────────────────────────
document.querySelectorAll('.itab').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.itab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const os = btn.getAttribute('data-os');
    document.getElementById('panel-npm').style.display    = os === 'npm'    ? '' : 'none';
    document.getElementById('panel-manual').style.display = os === 'manual' ? '' : 'none';
  });
});

// ── Copy buttons ──────────────────────────────────────────────────────────────
document.querySelectorAll('.copy-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const code = btn.getAttribute('data-code').replace(/&#10;/g, '\n');
    navigator.clipboard.writeText(code).then(() => {
      btn.textContent = 'Copied!';
      btn.classList.add('copied');
      setTimeout(() => {
        btn.textContent = 'Copy';
        btn.classList.remove('copied');
      }, 2000);
    }).catch(() => {
      // Clipboard API not available (e.g. non-HTTPS) — fail silently
    });
  });
});

// ── Smooth scroll for nav links  ──────────────────────────────────────────────
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const target = document.querySelector(a.getAttribute('href'));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});
